-- =====================================================================================
-- SIGMETA - DATOS DE DEMOSTRACION
-- Simulan la operacion de la ferreteria del 2026-08-03 al 2026-11-10 (hoy):
--   48 productos, 22 clientes, 8 proveedores, 24 compras, 34 cotizaciones, 15 ordenes de clientes,
--   125 ventas, 126 comprobantes (incluye 3 notas de credito), 120 despachos, 44 cuentas por cobrar,
--   42 cobros, 80 cajas con 147 movimientos y 80 cierres, 363 movimientos de inventario (kardex).
-- Todo cuadra con las reglas del BO: el stock es la suma de los movimientos del kardex, cada cuenta
-- por cobrar es el total menos sus notas de credito y sus cobros, y cada cierre cuadra con su caja.
--
-- !!! BORRA TODOS LOS DATOS DE LA BASE sigmeta (no toca las tablas ni los procedimientos). !!!
-- La base de AWS es COMPARTIDA por el grupo: avisar antes y sacar un respaldo
-- (Workbench > Server > Data Export) antes de ejecutarlo.
--
-- Usuarios (la clave de todos es Meta2026):
--   lrojas, cflores ............ Vendedor
--   mchavez, rsanchez .......... Cajero
--   jtorres .................... Almacenero
--   aquispe .................... Administrador
--   pmedina .................... Almacenero DESACTIVADO (conserva sus recepciones y despachos)
-- Hoy (2026-11-10) rsanchez tiene su caja abierta; mchavez no (sirve para demostrar la apertura).
-- =====================================================================================
USE sigmeta;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_SAFE_UPDATES = 0;

-- 1. LIMPIEZA (TRUNCATE tambien reinicia los AUTO_INCREMENT)
