TRUNCATE TABLE orden_compra_cliente;
TRUNCATE TABLE detalle_cotizacion;
TRUNCATE TABLE cotizacion;
TRUNCATE TABLE detalle_recepcion_compra;
TRUNCATE TABLE recepcion_compra;
TRUNCATE TABLE detalle_compra;
TRUNCATE TABLE compra;
TRUNCATE TABLE producto;
TRUNCATE TABLE categoria;
TRUNCATE TABLE solicitud_autorizacion;
TRUNCATE TABLE proveedor;
TRUNCATE TABLE cliente;
TRUNCATE TABLE usuario;
TRUNCATE TABLE rol;
TRUNCATE TABLE correlativo_documento;

