SET SQL_SAFE_UPDATES = 1;

-- Resumen de lo cargado
SELECT 'productos' AS tabla, COUNT(*) AS filas FROM producto UNION ALL SELECT 'clientes', COUNT(*) FROM cliente
UNION ALL SELECT 'compras', COUNT(*) FROM compra UNION ALL SELECT 'cotizaciones', COUNT(*) FROM cotizacion
UNION ALL SELECT 'ordenes de clientes', COUNT(*) FROM orden_compra_cliente UNION ALL SELECT 'ventas', COUNT(*) FROM venta
UNION ALL SELECT 'comprobantes', COUNT(*) FROM comprobante UNION ALL SELECT 'despachos', COUNT(*) FROM despacho
UNION ALL SELECT 'cuentas por cobrar', COUNT(*) FROM cuenta_por_cobrar UNION ALL SELECT 'cobros', COUNT(*) FROM cobro
UNION ALL SELECT 'cajas', COUNT(*) FROM caja UNION ALL SELECT 'movimientos de caja', COUNT(*) FROM movimiento_caja
UNION ALL SELECT 'cierres de caja', COUNT(*) FROM cierre_caja UNION ALL SELECT 'kardex', COUNT(*) FROM movimiento_inventario;

